import json

alert = self.full_execution["execution_argument"]
if isinstance(alert, str):
    alert = json.loads(alert)

try:
    hashes_str = alert["all_fields"]["data"]["win"]["eventdata"]["hashes"]
except Exception:
    hashes_str = ""

result = {}
for pair in hashes_str.split(","):
    if "=" in pair:
        k, v = pair.split("=", 1)
        result[k.strip().lower()] = v.strip()

print(json.dumps({
    "hash_values": list(result.values()),
    "sha256": result.get("sha256", ""),
    "count": len(result)
}))
